def transform(grid):
    h, w = len(grid), len(grid[0])

    # Divider rows/columns have a single dominant color; colored junctions
    # can interrupt them at a small number of positions.
    rows = [r for r in range(h)
            if max(grid[r].count(v) for v in set(grid[r])) >= w - 2]
    cols = [c for c in range(w)
            if max(sum(grid[r][c] == v for r in range(h))
                   for v in {grid[r][c] for r in range(h)}) >= h - 2]

    if not rows or not cols:
        return [[grid[0][0]]]

    # Read the divider intersections and discard consecutive duplicate
    # rows/columns, which represent repeated copies of the same marker.
    a = [[grid[r][c] for c in cols] for r in rows]

    def unique_consecutive(seq):
        out = []
        for x in seq:
            if not out or x != out[-1]:
                out.append(x)
        return out

    a = unique_consecutive(a)
    if a:
        a = [list(x) for x in zip(*a)]
        a = unique_consecutive(a)
        a = [list(x) for x in zip(*a)]

    # Trim uniform background-only border rows and columns.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    while len(a) > 1 and all(v == bg for v in a[0]):
        a.pop(0)
    while len(a) > 1 and all(v == bg for v in a[-1]):
        a.pop()
    while a and len(a[0]) > 1 and all(row[0] == bg for row in a):
        for row in a:
            row.pop(0)
    while a and len(a[0]) > 1 and all(row[-1] == bg for row in a):
        for row in a:
            row.pop()
    return a
